{"id":"44dc843b-3bcb-45ab-b60d-ba895562c965","inserted_at":"2026-07-07T22:57:55.234289+00:00","updated_at":"2026-07-07T22:57:55.234289+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- Esegui questo script nel SQL Editor di Supabase\r\n\r\n-- 1. Aggiungiamo la colonna mancante 'profile_completed' alla tabella profiles\r\n-- (Se il database è stato resettato di recente, questa colonna si era persa)\r\nALTER TABLE IF EXISTS public.profiles \r\nADD COLUMN IF NOT EXISTS profile_completed BOOLEAN DEFAULT false;\r\n\r\n-- 2. Ricreiamo la funzione in modo sicuro assicurandoci che corrisponda alla tabella\r\nCREATE OR REPLACE FUNCTION public.create_profile_for_new_user_fn()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n  INSERT INTO public.profiles (id, profile_completed, total_tokens)\r\n  VALUES (\r\n    NEW.id,\r\n    FALSE,\r\n    0\r\n  );\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\n-- 3. Assicuriamoci che il trigger sia correttamente collegato\r\nDROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;\r\nCREATE TRIGGER on_auth_user_created\r\n  AFTER INSERT ON auth.users\r\n  FOR EACH ROW EXECUTE FUNCTION public.create_profile_for_new_user_fn();","content_id":"44dc843b-3bcb-45ab-b60d-ba895562c965","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
